const SCHEDULE_DATA = [{"date":"2026-11-19T00:00:00","rooms":["Main stage","Breakout","Workshop"],"sessions":[{"id":"0d672722-a6ed-4525-861a-abb90f51cd57","title":"Registration and breakfast","description":"","startsAt":"2026-11-19T08:00:00","endsAt":"2026-11-19T09:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1306357","title":"Welcome to Cloud Native Denmark","description":"","startsAt":"2026-11-19T09:00:00","endsAt":"2026-11-19T09:15:00","room":"Main stage","isService":false,"speakers":["Jinhong Brejnholt","Allan Højgaard Jensen","Kasper Borg Nissen"],"format":null,"tags":[],"status":"Accepted"},{"id":"1333480","title":"HackYourFuture","description":"HackYourFuture Denmark helps people who face barriers entering the Danish tech industry build the skills, experience, and network needed to start a career in tech.\n\nIn this short keynote, Helena Birkholm, CEO of HackYourFuture Denmark, will introduce the organisation that Cloud Native Denmark is supporting this year and share how HackYourFuture works with trainees, volunteer mentors, and industry partners to turn technical training into real career opportunities.\n\nYou will hear who the program is for, how it works, what the support from Cloud Native Denmark will help make possible, and how people and companies in the tech community can contribute through mentoring, partnerships, and employment opportunities.\n\nBecause for talented people trying to enter the industry, access to the right community and that first opportunity can make all the difference.","startsAt":"2026-11-19T09:15:00","endsAt":"2026-11-19T09:25:00","room":"Main stage","isService":false,"speakers":["Helena Birkholm"],"format":"Keynote","tags":[],"status":"Accepted"},{"id":"1380632","title":"The Reinvention of Software Engineering","description":"I don’t need to tell you that AI has changed software development forever. You know this. Whether you’re positive, negative or indifferent to this change, you can’t deny that the past year has radically changed the role of the software developer.\n\nWhat does that mean for Platform Engineers? We build platforms to make developers more productive, more successful. That hasn't changed. The way we achieve this has shifted. \n \nI don’t offer a proven strategy to navigate this change, we are sailing these turbulent waters together. What I propose is that we go back to fundamentals, refocus on outcomes and evaluate our options for evolving our engineering practices and the platforms that support them.","startsAt":"2026-11-19T09:25:00","endsAt":"2026-11-19T09:50:00","room":"Main stage","isService":false,"speakers":["Hannah Foxwell"],"format":"Keynote","tags":["Platform Engineering","SDLC (Software Development Lifecycle)","Using AI"],"status":"Accepted"},{"id":"1267517","title":"A sterile patch is not a dirty fork","description":"Open-source projects move the world, but they are often maintained by few people with little time. Issues go stale, proposals remain theoretical, and pull requests can sit waiting for review, testing, or the next release. But your project does not have to wait.\n \nThis talk argues for getting comfortable with clean, intentional local patching: carrying small, well-documented changes while continuing to work upstream. Done well, patches can unblock teams, keep codebases clean, and make upstream contributions stronger.","startsAt":"2026-11-19T09:50:00","endsAt":"2026-11-19T09:55:00","room":"Main stage","isService":false,"speakers":["Johan Thomsen"],"format":"Lightning talk","tags":["Platform Engineering","Beginner"],"status":"Accepted"},{"id":"1263038","title":"OpenTelemetry Collector in Production: Real-World User Stories","description":"The OpenTelemetry Developer Experience SIG set out to answer a question the community kept asking: how do teams actually run the OpenTelemetry Collector in production? To find out, the SIG interviewed organizations across different industries and sizes.\n\nIn this lightning talk, you'll hear key highlights from these real-world user experiences: from running a lean setup that's never had a production incident, to simplifying pipelines at enterprise scale, to managing Collector configuration across dozens of Kubernetes clusters. Each story surfaces different trade-offs and practical lessons around deployment, configuration, and scaling.\n\nWith these use cases, you'll also be introduced to the OpenTelemetry Blueprints project, a community effort to help practitioners learn from real-world deployment patterns and skip the trial-and-error phase.\n\nYou'll walk away with insights into running the Collector in production, and a pointer to a growing set of reference implementations you can learn from and contribute to.","startsAt":"2026-11-19T09:55:00","endsAt":"2026-11-19T10:00:00","room":"Main stage","isService":false,"speakers":["Johanna Öjeling"],"format":"Lightning talk","tags":["Observability","Introduction"],"status":"Accepted"},{"id":"1306359","title":"Morning keynote wrap-up! Day one","description":"","startsAt":"2026-11-19T10:00:00","endsAt":"2026-11-19T10:05:00","room":"Main stage","isService":false,"speakers":["Kasper Borg Nissen","Jinhong Brejnholt","Allan Højgaard Jensen"],"format":null,"tags":[],"status":"Accepted"},{"id":"c233e3ec-7be3-41de-8a59-f35167053a1f","title":"Coffee break","description":"","startsAt":"2026-11-19T10:05:00","endsAt":"2026-11-19T10:25:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1263073","title":"Scaling the Agentic Web with Agent Substrate","description":"As we transition from \"Chat AI\" to autonomous agents, we face a massive infrastructure bottleneck: standard Kubernetes is designed for thousands of long-running services, but the future requires millions of bursty, stateful agent sessions. Standard control planes collapse under the \"chatter\" of sub-second tool calls, and idle containers waste millions in compute costs.\n\nThis talk introduces Agent Substrate, a Kubernetes-based system that achieves 30x+ oversubscription by treating agents as \"actors\" rather than traditional pods. We will dive into the architecture of Substrate, exploring how it uses gVisor-based sandboxing and instant state snapshots to \"suspend\" and \"resume\" agents in milliseconds. Attendees will learn how to bypass the limitations of the Kubernetes control plane to build hyper-scalable, framework-agnostic agent clouds that preserve filesystem and memory state across sessions.\n\nKey Takeaways:\n\nUnderstand why traditional pod-per-agent architectures fail at scale.\n\nUnderstanding the Substrate mapping of massive actor registries to \"warm\" worker pools.\n\nHow Substrate uses pod snapshots to hibernate and resume stateful agents with sub-second latency.\n\nHow to run LangChain, Claude Code, or MCP servers securely within Substrate sandboxes.","startsAt":"2026-11-19T10:25:00","endsAt":"2026-11-19T11:00:00","room":"Main stage","isService":false,"speakers":["Abdel Sghiouar"],"format":"Session","tags":["Platform Engineering","Security","Operating AI","Advanced"],"status":"Accepted"},{"id":"8935bf91-de91-44ef-8d58-43f538905d32","title":"Coffee break","description":"","startsAt":"2026-11-19T11:00:00","endsAt":"2026-11-19T11:20:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1263845","title":"Building platforms for teams that asked for them - and teams that didn't","description":"One of the sacred mantras of Platform Engineering is to treat our internal teams as customers. It's good advice, but it's a philosophy that assumes that the customer has a choice. What happens when they don't?\n\nOver the past three and a half years, I've been part of building two very different internal platforms at the LEGO Group: a Kubernetes platform that teams can adopt or reject, and an Observability platform with the purpose of company-wide consolidation. Same organisation, same customers, but a very different way of engaging those customers.\n\nThis talk considers what changes when users can opt out versus when they can't. Priorities change and success metrics change. How do you work with a team that was perfectly happy with what they had before, but can't have it anymore? How do we uphold the glorious banner of user centricity in the face of forced change?\n\nThis won't be very technical. We'll be talking about people, conversations, trust and how to work with teams - both within your own and towards others.","startsAt":"2026-11-19T11:20:00","endsAt":"2026-11-19T11:55:00","room":"Main stage","isService":false,"speakers":["Jacob Avlund"],"format":"Session","tags":["Platform Engineering","Operations + Performance","Observability"],"status":"Accepted"},{"id":"122d5df0-9e98-40b1-86d4-4112aa53cf54","title":"Coffee break","description":"","startsAt":"2026-11-19T11:55:00","endsAt":"2026-11-19T12:15:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1185995","title":"Observing Kubernetes Policies with Kyverno and VictoriaMetrics","description":"Kubernetes policies are often introduced to improve security and consistency, but once enabled they can be difficult to understand and troubleshoot. When a workload is rejected, teams frequently lack visibility into which policy was evaluated, how often it fails.\nThis talk presents a simple, technical workflow for observing Kubernetes policy behavior using Kyverno and VictoriaMetrics. Starting from a single validation policy, we show how policy evaluations and enforcement results are exposed as metrics, ingested into VictoriaMetrics and queried through a standard Prometheus-compatible API. A minimal dashboard is then used to inspect policy failures, affected namespaces and policy execution duration.\nThe talk focuses on making policy enforcement observable using standard Kubernetes primitives and open metrics, without assuming prior experience with policy engines or observability systems.","startsAt":"2026-11-19T12:15:00","endsAt":"2026-11-19T12:50:00","room":"Main stage","isService":false,"speakers":["Diana Todea","Cortney Nickerson"],"format":"Session","tags":["Platform Engineering","Operations + Performance","Security","Observability"],"status":"Accepted"},{"id":"b2bdbc9e-1a65-4aed-8377-14792de27243","title":"Lunch","description":"","startsAt":"2026-11-19T12:50:00","endsAt":"2026-11-19T14:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1263726","title":"Digital Sovereign Agentic Coding","description":"What does it take to develop your own local Agentic Coding framework?\nWhat tools is the right ones to get decent results?\nIs it even possible to do Agentic Coding with everything running locally on your laptop?\nIn this session we will share the lessons from building a local Agentic Coding framework the cloud native way running in containers locally on your laptop.\nWhat does it take to leave behind Claude Code or Codex?\nHow good is Open Weights LLMs actually and what does it take to make them work for coding?\nAs a extra benefit you will learn one way to achieve digital sovereignty when doing Agentic Coding.\nCome and hear about all the heard earned lessons about agentic coding, harness engineering, and how good Open Weights LLMs can be running locally on a laptop.","startsAt":"2026-11-19T14:00:00","endsAt":"2026-11-19T14:35:00","room":"Main stage","isService":false,"speakers":["Rasmus Steiniche"],"format":"Session","tags":["Platform Engineering","SDLC (Software Development Lifecycle)","Using AI","Operating AI","Digital Sovereignty","Deep Dive"],"status":"Accepted"},{"id":"b8d807b3-1746-4002-8bb8-bf6a82eb515d","title":"Coffee break","description":"","startsAt":"2026-11-19T14:35:00","endsAt":"2026-11-19T14:55:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1244358","title":"Unified Observability for PostgreSQL on Kubernetes: Logs, Traces, and Metrics under One Roof","description":"PostgreSQL observability is, today, a story told in three disconnected voices. Logs live in a log aggregator, metrics live in a time-series database, and traces, when they exist at all, stop at the application boundary, leaving the database as a black box at the bottom of every flame graph. The cost is not just operational fragmentation: it is the inability to follow a slow request from the user, through the application tier, into the SQL plan that actually produced the latency. For a system where the database is the most critical asset, this is the wrong default.\n\nThis talk shows how to unify the three pillars of observability for PostgreSQL clusters managed by CloudNativePG into a single, queryable backend. Query execution is instrumented inside PostgreSQL itself via pg_tracing, producing OpenTelemetry-compatible spans that join the application's distributed trace. Internal PostgreSQL statistics flow into a columnar analytical store through pg_stat_ch. Logs follow the same path. ClickHouse holds all three streams under one schema, and Grafana queries them as a single source: one pane of glass for everything PostgreSQL on Kubernetes is doing, from query plan to disk write.","startsAt":"2026-11-19T14:55:00","endsAt":"2026-11-19T15:30:00","room":"Main stage","isService":false,"speakers":["Gabriele Rossini"],"format":"Session","tags":["Operations + Performance","Observability","Beginner"],"status":"Accepted"},{"id":"c7470e6c-2877-43ac-b930-85323bb57049","title":"Coffee break","description":"","startsAt":"2026-11-19T15:30:00","endsAt":"2026-11-19T16:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1168958","title":"Whose Code is it Anyways?","description":"Open source contributors can now move at previously unthinkable speeds — which is great — but can leave senior maintainers drowning in a sea of shoddy PRs and junior developers unable to grow when the pressure is for seniors to do everything!\n\nIn this talk, Adriana and Josh discuss bidirectional empathy through the lens of cloud native contributions in the AI era. You will hear about putting in guardrails for AI-assisted pull requests (PRs), ensuring quality PRs from contributors, how to be open-minded to new ideas, ensuring that suggestions from juniors aren't shot down by seniors, and how to confront resistance to change (without making enemies).\n\nLet's pass the torch to the next generation of cloud native contributors and community maintainers, and ensure junior developers don't become an endangered species.","startsAt":"2026-11-19T16:00:00","endsAt":"2026-11-19T16:25:00","room":"Main stage","isService":false,"speakers":["Adriana Villela","Josh Lee"],"format":"Keynote","tags":["Observability"],"status":"Accepted"},{"id":"1268490","title":"What goblins and druids can teach us about enterprise AI","description":"You'd think AI would be great at running a D&D game. The whole game's structured hallucination, and the rules are written down. The first week was magic. Then it got boring, repetitive, and kind of bad at remembering anything that happened more than an hour ago.\n\nFixing that's what got me into the actual guts of agentic AI. And after a while it stopped being a D&D problem and started being the same problem people at work keep asking me about: where does this capability go? Is it a prompt I paste in? A skill the model loads when it feels like it? An MCP server I stand up and let any AI client call? Who owns it when it breaks?\n\nThis talk's about this adventure and its twists and turns: Agent Skills vs. MCP servers, with D&D as the running example because the failure modes are funny instead of career-ending. I'll walk through what I built and learned along the way.\n\nThere's also the boring half, which is the half that matters for the real world: governance. Who owns the capability. How it gets versioned and shipped. Where the secrets live. Who's allowed to call it. How you know what it's doing. What it costs. How you roll back when somebody pushes a change that makes every NPC speak in haiku.\n\nThis'll give you a working mental model for how to architect and manage your corporate AI projects. And give you an excuse to play D&D on company time.","startsAt":"2026-11-19T16:25:00","endsAt":"2026-11-19T16:50:00","room":"Main stage","isService":false,"speakers":["Michael Coté"],"format":"Keynote","tags":["Platform Engineering","Using AI"],"status":"Accepted"},{"id":"1306361","title":"Closing remarks! Day one","description":"","startsAt":"2026-11-19T16:50:00","endsAt":"2026-11-19T17:00:00","room":"Main stage","isService":false,"speakers":["Jinhong Brejnholt","Allan Højgaard Jensen","Kasper Borg Nissen"],"format":null,"tags":[],"status":"Accepted"},{"id":"00f903bb-9cf1-41c6-82da-0b985b988450","title":"Sponsor crawl","description":"Visit our sponsors' booths and meet the teams supporting Cloud Native Denmark while enjoying a welcome drink on us.","startsAt":"2026-11-19T17:00:00","endsAt":"2026-11-19T18:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"f8e322b8-3764-4a6c-a336-0e501dc6d929","title":"After party - sponsored by Upwind","description":"Join fellow attendees, speakers, sponsors and organisers for a relaxed evening of good conversations, tapas and drinks.\nContinue a technical discussion, make new connections or indulge in the age-old Danish tradition of complaining about the weather!\nThe after-party is included in your conference ticket if you selected it during registration.","startsAt":"2026-11-19T18:00:00","endsAt":"2026-11-19T21:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1168972","title":"The lazy developer’s guide to observing your own code","description":"We keep telling developers they need to instrument their own code with OpenTelemetry (OTel). When they do, it feels like they’re doing it for the benefit of others, like SREs. Observability can benefit developers too, but it feels too complicated, and as a result Observability is treated as a second-class citizen.\n\nThis talk changes that by motivating developers to troubleshoot their own code with OTel. Developers will learn:\n* Why do it?\n* Basic overview of OTel instrumentation concepts\n* Overview of desktop tooling for developers to visualize OTel data\n* How to add meaningful traces, metrics, and logs to your code with minimal changes\n* A practical, repeatable workflow for using OTel to troubleshoot code\n* Common pitfalls (like accidental high cardinality) and how to avoid them\n* A live demo putting it all together\n\nDevelopers will walk away with the confidence to instrument and troubleshoot their own code with OTel.","startsAt":"2026-11-19T10:25:00","endsAt":"2026-11-19T11:00:00","room":"Breakout","isService":false,"speakers":["Adriana Villela","Diana Todea"],"format":"Session","tags":["Observability"],"status":"Accepted"},{"id":"1248242","title":"Do You Trust Your PodDisruptionBudgets? You Shouldn’t!","description":"Have you ever trusted your PodDisruptionBudget, only to watch Kubernetes evict your pods anyway? PodDisruptionBudgets feel like a safety net, but in reality, they’re not the silver bullet many expect. Under the hood, priority classes, rolling restarts and resource pressure can silently bypass your budgets: leaving critical workloads exposed during upgrades, reschedules, or node failures. In this session, we’ll walk through real-world failure scenarios, how it impacted our platform, show how to reproduce them, and share practical strategies to test and harden your disruption policies so your workloads truly stay protected.","startsAt":"2026-11-19T11:20:00","endsAt":"2026-11-19T11:55:00","room":"Breakout","isService":false,"speakers":["Kārlis Akots Gribulis"],"format":"Session","tags":["Platform Engineering","Beginner","Introduction","Deep Dive"],"status":"Accepted"},{"id":"1261289","title":"Building a US-Independent Fallback Environment: Successes, Failures, and the Hidden Traps","description":"Most teams talk about cloud sovereignty and provider-exit. Almost nobody has actually built it and can tell you what it costs. This is the real story of building a US-independent fallback environment for a European telematics platform running half a million connected assets: how we selected the solutions and why, and the genuinely hard parts of making sure the core can run outside the major cloud providers at all. Pain and all.\n\nTo be clear, we're not leaving the US owned cloud unless we have to. The point is to be ready if we're ever forced. Everything is built from open source parts you can reproduce yourself, Kafka, HiveMQ, MinIO,OpenBao, GitLab, Harbor, and ArgoCD, so there's no vendor lock and no \"only works at our budget.\"\n\nAnd it's an honest account of an ongoing journey, including the part most architecture talks skip: resilience turned out to be an organisational property as much as a technical one. One person quietly owning 13+ systems was a bigger DR risk than any single component we designed around. You'll leave with the solution-selection reasoning, a concrete map of where running outside the big providers actually bites, and the successes, failures, and hidden traps from a project that's still very much underway.","startsAt":"2026-11-19T12:15:00","endsAt":"2026-11-19T12:50:00","room":"Breakout","isService":false,"speakers":["Thomas Ornell"],"format":"Session","tags":["Platform Engineering","Operations + Performance","Observability","Digital Sovereignty","Beginner"],"status":"Accepted"},{"id":"1262448","title":"No SSH, No Golden Image, No Snowflakes: Provisioning Bare Metal from a Single Kubernetes Cluster","description":"The cloud taught us to see servers as cattle. But then we shifted back to bare metal and realized they're hefty cattle that sit in a rack, in a building, with a power button. This talk dives into bridging that gap: running a bunch of physical EPYC servers as easily as you’d manage anything on a hyperscaler – and never once SSHing into a node, 'cause there’s no SSH to rely on.\n\nWe’ll follow the process that transforms a powered-off server into a Kubernetes node without any manual intervention: Metal3 and Ironic discover and power-manage the hardware through Redfish/IPMI, while Cluster API's Metal3 and Talos providers outline the desired cluster, and Talos Linux – immutable, API-driven, no shell – boots up and configures itself. The tricky part? Bootstrapping the very first cluster and switching Cluster API onto the newly created cluster, so the management plane can manage itself.\n\nI’ll explore what’s genuinely magical, what tripped us up, and the reality of operating declarative bare metal.","startsAt":"2026-11-19T14:00:00","endsAt":"2026-11-19T14:35:00","room":"Breakout","isService":false,"speakers":["Karsten Nielsen"],"format":"Session","tags":["Platform Engineering","Advanced","Deep Dive"],"status":"Accepted"},{"id":"1227383","title":"How we used Crossplane for the things we should not have","description":"Frameworks are meant to be tweaked, that is just a part of being an engineer. Even if a new cloud native, open source framework is exactly what you are attempting to build. \nThis talk tells the story of what Crossplane is and what we wanted it to be. It highlights the need for the Crossplane 2, and why they are different. It also illustrates a real-life story when bending leads to breaking, resulting in the loss of 230 production databases for a customer during maintenance. The silver lining - we kept the customer, but changed our approach.","startsAt":"2026-11-19T14:55:00","endsAt":"2026-11-19T15:30:00","room":"Breakout","isService":false,"speakers":["Liene Luksika"],"format":"Session","tags":["Platform Engineering","Introduction"],"status":"Accepted"},{"id":"1260102","title":"PostgreSQL on Kubernetes: A Hands-On Introduction to CloudNativePG","description":"Many engineers are comfortable running stateless workloads on Kubernetes, but still reach for a managed database the moment state enters the picture.\n\nThis workshop is a hands-on introduction to doing it differently, using CloudNativePG, the CNCF operator for running PostgreSQL natively on Kubernetes.\n\nWe'll work entirely inside the \"cnpg-playground\", the project's open local learning environment, which spins up two Kubernetes clusters and object storage on your laptop. You'll start with a single cluster — deploying it, connecting to it and exploring what the operator manages on your behalf.\n\nFrom there, we'll look at high availability: a controlled switchover, then deliberately removing the primary to watch the operator recover. We'll set up continuous backup to object storage and walk through recovery, including point-in-time recovery from a simulated mistake.\n\nFinally, we'll go from one cluster to two, bootstrapping a replica cluster in the second region to explore distributed topologies.\nThe goal is intuition, not mastery: by the end, you'll understand how CloudNativePG thinks, what it does for you and where to look next.\n\nEverything uses upstream CloudNativePG and open tooling, so the patterns travel wherever your clusters run.","startsAt":"2026-11-19T10:25:00","endsAt":"2026-11-19T11:55:00","room":"Workshop","isService":false,"speakers":["Gabriele Bartolini"],"format":"Workshop","tags":["Digital Sovereignty","Data"],"status":"Accepted"},{"id":"1257353","title":"Getting started with OpenTelemetry instrumentation: A practical playbook","description":"OpenTelemetry has become an essential open source framework for standardizing telemetry data. In this beginner-friendly hands-on lab, you’ll walk through the journey of instrumenting an application with OpenTelemetry and sending metrics, logs, and traces to the Grafana LGTM stack (Loki for logs, Grafana for visualization, Tempo for traces, and Prometheus for metrics).\n\nYou’ll learn common instrumentation approaches, such as adding application-level telemetry using the OpenTelemetry SDK, collecting basic infrastructure metrics with the OpenTelemetry Collector, and implementing cross-service communication with zero-code eBPF instrumentation. You’ll also apply practical customization techniques, such as enriching and sampling spans, tuning metrics, and adding your own signals when auto-instrumentation isn’t enough.\n\nBy instrumenting a sample application step by step, you’ll leave this lab with a clear roadmap for choosing the right OpenTelemetry instrumentation approach within your own environment.\n\nBy the end of the three hours, you will:\n\n- Have a core understanding of the OpenTelemetry project and its key components\n- Select the right level of instrumentation based on various use cases\n- Understand how zero-code eBPF instrumentation helps reveal cross-service communication\n- Instrument applications using OpenTelemetry SDKs\n- Apply end-to-end instrumentation patterns to get started quickly and improve over time\n- Send telemetry to the Grafana stack and understand how it’s used","startsAt":"2026-11-19T14:00:00","endsAt":"2026-11-19T15:30:00","room":"Workshop","isService":false,"speakers":["Imma Valls","Arthur Picerna"],"format":"Workshop","tags":["Observability","Introduction"],"status":"Accepted"}]},{"date":"2026-11-20T00:00:00","rooms":["Main stage","Breakout","Workshop"],"sessions":[{"id":"98afb4b6-c846-4762-a548-d45679c09617","title":"Registration and breakfast","description":"","startsAt":"2026-11-20T08:00:00","endsAt":"2026-11-20T09:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1306364","title":"Welcome to day two!","description":"","startsAt":"2026-11-20T09:00:00","endsAt":"2026-11-20T09:10:00","room":"Main stage","isService":false,"speakers":["Jinhong Brejnholt","Kasper Borg Nissen","Allan Højgaard Jensen"],"format":null,"tags":[],"status":"Accepted"},{"id":"1259491","title":"The Developer’s Nightmare: How To Survive Compliance Checklists (and Still Ship Fast)","description":"You did it! The new feature you’ve been implementing is now ready and you can’t wait to ship it.\n\n“Not so fast”. Oh no, it’s them: the guardians of compliance! You know what’s about to happen. You’ve been there before.\n\n- Are you using any license that is not approved?\n- Is there any CVE reported for the new dependencies you added?\n- Can you guarantee the artifact running in production has not been tampered with?\n\nSeveral checklists, paperwork, and meetings later, you’re finally approved for release. Not fun. Where did the developer joy go?\n\nIn this session, Alexandra and Thomas explore how to break the compliance barriers for developers, even in highly-regulated industries. The goal is to enhance the developer experience while letting the platform automate and enforce compliance and security checks.\n\nYou'll follow the mishaps of a developer and learn how to deal with compliance, using practical solutions based on OSS tools like Backstage, Dependency-Track, Sigstore and Buildpacks.","startsAt":"2026-11-20T09:10:00","endsAt":"2026-11-20T09:35:00","room":"Main stage","isService":false,"speakers":["Thomas Vitale","Alexandra Hou Aldershaab"],"format":"Keynote","tags":["SDLC (Software Development Lifecycle)","Security"],"status":"Accepted"},{"id":"1371596","title":"Sponsor Keynote: GPUaaS on Kubevirt. How hard can it be?","description":"The foundation of our AI platforms is GPUaaS. We chose to build GPUaaS on something we truly believe in - Kubevirt! Like last year with Multi-Site Ceph, we're now ready to share a bit about our journey, filled with ups, downs, brick walls and other fun stuff.","startsAt":"2026-11-20T09:35:00","endsAt":"2026-11-20T09:50:00","room":"Main stage","isService":false,"speakers":["Michael Munk Lassen"],"format":"Keynote","tags":["Operations + Performance","Operating AI","Digital Sovereignty"],"status":"Accepted"},{"id":"349f342a-efd2-47cc-98b8-c94872e45802","title":"Gold sponsor pitches","description":"","startsAt":"2026-11-20T09:50:00","endsAt":"2026-11-20T10:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1306365","title":"Morning keynote wrap-up! Day two","description":"","startsAt":"2026-11-20T10:00:00","endsAt":"2026-11-20T10:05:00","room":"Main stage","isService":false,"speakers":["Jinhong Brejnholt","Kasper Borg Nissen","Allan Højgaard Jensen"],"format":null,"tags":[],"status":"Accepted"},{"id":"b0bdb58d-1cb7-4b52-b9c5-f29a33ff82c0","title":"Coffee break","description":"","startsAt":"2026-11-20T10:05:00","endsAt":"2026-11-20T10:25:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1254389","title":"Trust Me, I’m Internal: Building a Custom Root of Trust for Kubernetes Workloads","description":"Many organizations want their application and platform stack to trust an internal certificate authority instead of, or in addition to, the public Web PKI. This sounds simple: “just add the CA certificate.” In practice, it quickly becomes a platform-wide problem involving node trust stores, workload injection, admission control, different language runtimes, and developer experience.\n\nIn this talk, we will share practical lessons from building Custom Root of Trust support for Kubernetes environments used in regulated and security-sensitive settings. The goal was to make internal trust manageable for platform administrators while keeping application teams productive and protected from subtle TLS misconfigurations.\n\nWe will walk through the design and operational choices behind the implementation: preparing Kubernetes nodes to trust internal CAs, using cert-manager and trust-manager to provision and distribute trust bundles, and using Kyverno policies to inject the right certificates into Pods. We will also cover the trade-offs between OptIn and OptOut injection models, how admission control can prevent broken deployments, and why “standard” environment variables like SSL_CERT_FILE are not enough for every application.\n\nThe talk will include a demo showing how custom CA bundles can be distributed and injected into workloads, as well as some of the implementation challenges that appear along the way. We will demonstrate examples such as validating bundle references, handling misconfigured annotations, and adapting the approach for runtimes like Java, Node.js, and applications using the AWS SDK, where each runtime handles trust stores differently. We will also share the lessons learned from trying to make this feature safe by default, understandable for developers, and suitable for environments where external dependencies must be minimized.","startsAt":"2026-11-20T10:25:00","endsAt":"2026-11-20T11:00:00","room":"Main stage","isService":false,"speakers":["Jakub Krzywda","Cristian Klein"],"format":"Session","tags":["Platform Engineering","Security","Digital Sovereignty"],"status":"Accepted"},{"id":"5cfb0b2f-9d71-41c5-8475-cbb855ab8569","title":"Coffee break","description":"","startsAt":"2026-11-20T11:00:00","endsAt":"2026-11-20T11:20:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1196628","title":"Your platforms matter more than ever with AI","description":"Without a clear strategy your agentic coding will accelerate fragmentation! Different tools, inconsistent environments and ad hoc processes will compound into chaos at machine speed. But with a qualitative internal platform, standardized workflows and paved roads, AI becomes a multiplier for quality and consistency instead of risk.\n\nAt the same time, each developer will likely be responsible for more software than ever before. As output increases, cognitive load must decrease. That means less variability, fewer bespoke setups and stronger defaults. The complexity of the systems must go down even if the volume of code goes up.\n\nInternal developer platforms are no longer a productivity initiative. They are a prerequisite for succeeding in the AI era of software development!\n\nJoin this session to get the blue print strategy for accelerating agentic efficiency with internal platforms!","startsAt":"2026-11-20T11:20:00","endsAt":"2026-11-20T11:55:00","room":"Main stage","isService":false,"speakers":["Jessica Andersson"],"format":"Session","tags":["Platform Engineering"],"status":"Accepted"},{"id":"b2fcd2d5-d8d8-402b-800f-9cf38aa47135","title":"Coffee break","description":"","startsAt":"2026-11-20T11:55:00","endsAt":"2026-11-20T12:15:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1247050","title":"Observability in the Matrix: Choosing the Right AI Agent to Escape the Chaos","description":"In a world flooded with metrics, logs, and traces does AI-driven observability help us escape the chaos, or does it simply build a more sophisticated illusion? You wake up in a Kubernetes cluster that seems fine until latency spikes, noisy logs, and missing traces reveal the truth: you're in the Observability Matrix. In this talk, we’ll guide you through five AI-powered agents: HolmesGPT, Kagent, Opni, K8sGPT, and Monte Carlo; each offering a different pill to help you escape the chaos. Like Neo choosing between red and blue, you’ll learn how these tools uncover root causes, enrich signals, reduce alert fatigue, and trace the behavior of autonomous agents. But beware: not all AI is your ally. We’ll explore the promises and pitfalls of AI-driven observability, and how to avoid being trapped in a false sense of insight. Join us for a journey through the Matrix of metrics, logs, and traces—and leave with the knowledge to choose your observability destiny.","startsAt":"2026-11-20T12:15:00","endsAt":"2026-11-20T12:50:00","room":"Main stage","isService":false,"speakers":["Henrik Rexed"],"format":"Session","tags":["Observability","Operating AI"],"status":"Accepted"},{"id":"df01b871-f4c9-4869-8f11-c5b0dacd6ae1","title":"Lunch","description":"","startsAt":"2026-11-20T12:50:00","endsAt":"2026-11-20T14:00:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1263748","title":"Durable Execution at Uber Scale: Orchestrating Multi-Region Resilience with Cadence","description":"At Uber, downtime is not an option. Behind the scenes, our open-source workflow engine, Cadence, manages millions of concurrent executions. But how do you safely run and recover large, stateful workloads when a whole geographic region fails?\n\nAchieving regional resilience for workflows is difficult. You have to deal with data replication lag, prevent split-brain scenarios, and make sure tasks are not lost or duplicated across regions.\n\nYou will learn about the built-in Cadence features we use for precise failovers, and how we turn massive regional resiliency drills into a routine, everyday task instead of a stressful emergency.","startsAt":"2026-11-20T14:00:00","endsAt":"2026-11-20T14:35:00","room":"Main stage","isService":false,"speakers":["Seva Kaloshin"],"format":"Session","tags":["Platform Engineering"],"status":"Accepted"},{"id":"00683449-a760-4776-b017-0b2d6965fee9","title":"Coffee break","description":"","startsAt":"2026-11-20T14:35:00","endsAt":"2026-11-20T14:55:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1245182","title":"The AI side effects we’re not talking about","description":"It’s time for a frank, and possibly uncomfortable, talk about the future of our profession.\n\nThis isn't a talk about carbon footprints, training data ethics, or the non-deterministic nature of LLMs. We’ve heard those (valid) arguments.\n\nThis talk is about us - the engineers, the developers, and the various practitioners in the software industry. Regardless of whether you’ve embraced AI or are resisting it, the structural impact on our industry is already here.\n\nTogether we will examine the immediate erosion of the engineering craft, the shift from software engineer to software approver and look toward the more dangerous, unseen consequences: the potential collapse of the junior-to-senior talent pipeline and the long-term degradation of the technical capabilities that defines our industry.\n\nHopefully having these concerns in mind means we can work together to avoid them and ensure our industry continue to thrive far into the future.","startsAt":"2026-11-20T14:55:00","endsAt":"2026-11-20T15:30:00","room":"Main stage","isService":false,"speakers":["Marcus Noble"],"format":"Session","tags":["Using AI"],"status":"Accepted"},{"id":"b7ae861f-3ad6-4eee-9f2b-4c805a69ecda","title":"Coffee break","description":"","startsAt":"2026-11-20T15:30:00","endsAt":"2026-11-20T15:50:00","room":"Main stage","isService":true,"speakers":[],"format":null,"tags":[],"status":null},{"id":"1260088","title":"Beyond the DBaaS Trap: Achieving Data Sovereignty With Kubernetes and CloudNativePG","description":"Digital sovereignty requires \"operational sovereignty\", that is, the ability to run critical workloads on any infrastructure without proprietary cloud API limits.\nAs global regulations like the EU Data Act set new standards for data portability, organisations must prioritise architectures that ensure long-term independence.\nManaged databases (DBaaS) are the primary point of lock-in, creating a \"gravity\" that makes migration to sovereign clouds difficult.\nGabriele, co-founder and maintainer of CloudNativePG, shows how to address this using Kubernetes to build a cloud-neutral PostgreSQL architecture that satisfies modern sovereignty requirements.\nAttendees will explore how to meet business continuity requirements that remain identical across hyperscalers and bare metal, while learning practical strategies for data-level portability. This approach ensures an organisation can move its most critical asset and adapt as regulatory requirements evolve, without sacrificing the developer experience.","startsAt":"2026-11-20T15:50:00","endsAt":"2026-11-20T16:15:00","room":"Main stage","isService":false,"speakers":["Gabriele Bartolini"],"format":"Keynote","tags":["Digital Sovereignty","Data"],"status":"Accepted"},{"id":"1306366","title":"Thank you, surprises, and raffles","description":"","startsAt":"2026-11-20T16:15:00","endsAt":"2026-11-20T16:35:00","room":"Main stage","isService":false,"speakers":["Jinhong Brejnholt","Kasper Borg Nissen","Allan Højgaard Jensen"],"format":null,"tags":[],"status":"Accepted"},{"id":"1260733","title":"Two Standards Walk Into an Agent: Runtime Agent Control with OpenTelemetry and OpenFeature","description":"Autonomous agents are being deployed without runtime control. No open, vendor-neutral way to change what they do. No visibility into why they decided. We can fix that. A physical party game. A Raspberry Pi. An agent that adapts and evolves the game in real time. Without a single proprietary platform.\n\nSounds fun. But it's also the argument. We've been here before.\n\nEvery vendor built their own observability stack. We paid the price - so we built OpenTelemetry. Same with feature flags - we built OpenFeature.\n\nNow agents are here. The control layer is emerging again, often as vendor-specific infrastructure.\n\nNobody designed OpenTelemetry to be an agent's eyes. Nobody designed OpenFeature to be its conscience. Turns out they work anyway: OpenTelemetry becomes observation, OpenFeature becomes control.\n\nThis talk explores agent control on open standards — physical system control, infrastructure management, live model switching, permission changes, and rollback without redeployment.\n\nEvery autonomous agent needs a control layer. Vendors are racing to own it. You already have it.","startsAt":"2026-11-20T10:25:00","endsAt":"2026-11-20T11:00:00","room":"Breakout","isService":false,"speakers":["Simon Schrottner"],"format":"Session","tags":["SDLC (Software Development Lifecycle)","Observability","Using AI"],"status":"Accepted"},{"id":"1205020","title":"Beyond the Data Swamp: Building Your Semantic Observability Mesh","description":"Most engineering teams are currently drowning in a \"data swamp\". We collect more logs, metrics, and traces than ever before, yet when a critical system fails, we still feel blind.\n\nThe problem isn’t a lack of data; it is a lack of shared understanding. This session explores how to move away from disconnected silos toward a Semantic Observability Data Mesh.\n\nWe will share a journey of transforming raw, expensive telemetry into a powerful and unified asset. We will demonstrate how ClickHouse provides the high-speed engine needed to process data at scale without breaking the budget.\n\nHowever, the real magic happens when we give that data context and meaning. We will move beyond standard OpenTelemetry conventions to show how you can build and extend your own custom semantic layers.\n\nFinally, by using Weaver to validate these schemas, you can ensure your systems all speak the same language.\n\nYou will learn how to turn a chaotic sea of noise into a searchable, reliable source of truth that reveals the root cause of problems in seconds.","startsAt":"2026-11-20T11:20:00","endsAt":"2026-11-20T11:55:00","room":"Breakout","isService":false,"speakers":["Graziano Casto","Josh Lee"],"format":"Session","tags":["Observability"],"status":"Accepted"},{"id":"1148240","title":"Make Sovereign Cloud Boring: One Binary to Run Kubernetes Anywhere","description":"Getting multi-cloud wrong is easy, but building a truly sovereign stack across many cloud providers is hard.\n\nThe platform team at Corti.ai has built an open-source infrastructure platform to commoditize compute, storage, and networking, to simplify the deployment of kubernetes based workloads across any cloud provider.\n\nKommodity.io combines the power of Talos Linux and the Kubernetes Cluster API into a single binary to power the sovereign backbone of your digital infrastructure. With Kommodity you can deploy your infrastructure across cloud providers, virtualization and bare-metal using the same configuration.\n\nThis session is an advanced deep dive session, where we will explain how we have combined several components of the Kube API Server with a networked KMS, Kine and a custom Metadata server, so that we can provide a single interface for compliant disk encryption and operations via kubectl and helm.\n\nGithub: https://github.com/kommodity-io/kommodity\nPodcast on Kommodity: https://www.corti.ai/builder-series/solving-cloud-lock-in-and-gpu-shortages","startsAt":"2026-11-20T12:15:00","endsAt":"2026-11-20T12:50:00","room":"Breakout","isService":false,"speakers":["Steffen Karlsson","Nicklas Frahm"],"format":"Session","tags":["Platform Engineering","Security","Operating AI","Digital Sovereignty","Advanced","Deep Dive"],"status":"Accepted"},{"id":"1252414","title":"Operators in Action: Making Kubernetes Work for You","description":"When our team needed to automate the creation of multiple app instances, we quickly realized that existing tools weren’t enough. Writing a custom operator turned out to be the most practical way to manage their lifecycle — and a surprisingly effective way to see how Kubernetes works under the hood.\n\nIn this talk, I’ll walk you through the lessons learned while building an operator for a real-world multi-service application. We’ll explore designing Custom Resources, implementing reconciliation logic, and handling state and configuration challenges. Along the way, I’ll share the pitfalls I ran into, debugging tricks that helped, and the patterns that made the operator framework click.\n\nWhether you’re curious about what goes on behind the scenes in Kubernetes operators or planning to build one yourself, you’ll leave with practical tips and a clear roadmap to get started confidently.","startsAt":"2026-11-20T14:00:00","endsAt":"2026-11-20T14:35:00","room":"Breakout","isService":false,"speakers":["Verena Traub"],"format":"Session","tags":["Platform Engineering","Operations + Performance","Introduction"],"status":"Accepted"},{"id":"1206116","title":"It's my Cloud! Building On-Demand Kubernetes Platforms at Home","description":"In business settings, the path to Kubernetes often feels straightforward: choose a cloud provider, spin up a managed environment, and rely on a team to keep everything running. But what if you could build and run your own platform at home - one that’s self-managed, integrated into your local network, and still practical without round-the-clock attention?\n\nIn this talk, I’ll share my journey of experimenting with self-managed on-demand Kubernetes platforms at home, a mix of fun experiments, hard lessons, and a few happy rediscoveries (hello again, Proxmox!). You’ll see how I used GitHub for management, integrated Kubernetes with virtualization and my home network, and kept everything manageable without burning out.\n\nYou’ll leave with practical tips on:\n\n* Bootstrapping platforms outside of big cloud providers\n* Avoiding common homelab pitfalls\n* Integrating Kubernetes with tools like Proxmox\n\nWhether you’re curious about Kubernetes internals, exploring platform engineering beyond the cloud, or just tinkering with homelabs, this talk will give you practical takeaways and maybe spark ideas for your own experiments.","startsAt":"2026-11-20T14:55:00","endsAt":"2026-11-20T15:30:00","room":"Breakout","isService":false,"speakers":["Thomas Schuetz"],"format":"Session","tags":["Platform Engineering","Advanced"],"status":"Accepted"},{"id":"1212635","title":"What is... Regenerative Software Development","description":"Are our software systems in balance, running wild, or approaching a halt?\n\nInspired by Gregory Bateson’s cybernetics, this Lean Coffee Workshop explores what it takes to make software development regenerative — moving beyond pure extraction and exploitation to embrace the full lifecycle of a system, where even decay and sunsetting feed new growth.\n\nIf we want to make the world better — at least the world of software. How do we do that? Bring your coffee and your curiosity as we explore this together.\n\n\"Software is Born Free — And Everywhere it is in Chains\"","startsAt":"2026-11-20T10:25:00","endsAt":"2026-11-20T11:55:00","room":"Workshop","isService":false,"speakers":["Lars Kruse"],"format":"Workshop","tags":["SDLC (Software Development Lifecycle)"],"status":"Accepted"},{"id":"1263082","title":"Building Platforms with Crossplane: A Hands-On Introduction","description":"In this hands-on workshop, we'll take you from zero to building your first internal developer platform with Crossplane. Whether you've heard about Crossplane but never touched it, or built a small PoC but got stuck going further, this workshop is for you.\n\n\nWho should attend\n\nDevOps engineers, platform engineers, cloud engineers, and technical leads who want a practical, guided introduction to Crossplane. Beginner-friendly - no prior Crossplane experience required.\n\n\nWhat you'll learn\n\nBy the end of this workshop, you will:\n- Understand what Crossplane is, how it works, and when it makes sense to use it (vs. alternatives like a Terraform module in a pipeline)\n- Know the core building blocks: Providers, Managed Resources, Composite Resource Definitions (XRDs), Compositions, and Functions\n- Be able to create managed resources and write a basic Composition for a real-world use case\n- Understand how Crossplane fits into the bigger picture: GitOps, platforms, and team self-service\n\n\nHow it works\n\nThe workshop is split into three parts:\n1. Short intro on key Crossplane concepts\nA focused introduction covering Crossplane's architecture and resources, how it extends Kubernetes with CRDs and controllers, and where it fits in the IaC and platform engineering landscape.\n2. Hands-On Lab\nWorking in small teams (or solo), you'll build a working platform from a curated set of guided exercises. \n3. Wrap-up and your questions\nA dedicated slot for your questions and to talk about real-world experience: what works, what doesn't, and how to go from workshop to production. We'll cover how to organize your code and repos, and what the path looks like to roll out Crossplane in an organization.\n\n\nHow to prepare\n\nYou bring the laptop, we give you the environment. Nothing else needed (except a Github account). \n\n\nWhat we expect from you \n\n- Basic Kubernetes knowledge: you can use kubectl, you know what a Deployment and a Service are, and you've heard of CRDs and controllers \n- An idea of what IaC and GitOps mean - not intricate setups, just the general principles\n\n\nBonus\n\nWhat we can optionally dive into during the Q/A session:\n\n- Using different languages for Compositions (Python, KCL, Go)\n- Writing a custom provider or function\n- Packaging configurations into OCI images with dependency management\n- Setting up Crossplane with ArgoCD / GitOps\n- Integration with policy engines (OPA, Kyverno)\n- Testing strategies: rendering, assertions, and E2E","startsAt":"2026-11-20T14:00:00","endsAt":"2026-11-20T15:30:00","room":"Workshop","isService":false,"speakers":["Riccardo Capraro"],"format":"Workshop","tags":["Platform Engineering","Beginner","Advanced"],"status":"Accepted"}]}];